# use cache
## Serialization [Link to this section](https://nextjs.org/docs/app/api-reference/directives/use-cache#serialization)
### Pass-through (non-serializable arguments) [Link to this section](https://nextjs.org/docs/app/api-reference/directives/use-cache#pass-through-non-serializable-arguments)
```
async function CachedWrapper({ children }: { children: ReactNode }) {
  'use cache'
  // Don't read or modify children - just pass it through
  return (
    <div className="wrapper">
      <header>Cached Header</header>
      {children}
    </div>
  )
}

// Usage: children can be dynamic
export default function Page() {
  return (
    <CachedWrapper>
      <DynamicComponent /> {/* Not cached, passed through */}
    </CachedWrapper>
  )
}
```

## Constraints [Link to this section](https://nextjs.org/docs/app/api-reference/directives/use-cache#constraints)
### React.cache isolation [Link to this section](https://nextjs.org/docs/app/api-reference/directives/use-cache#reactcache-isolation)
```
import { cache } from 'react'

const store = cache(() => ({ current: null as string | null }))

function Parent() {
  const shared = store()
  shared.current = 'value from parent'
  return <Child />
}

async function Child() {
  'use cache'
  const shared = store()
  // shared.current is null, not 'value from parent'
  // use cache has its own isolated React.cache scope
  return <div>{shared.current}</div>
}
```
